using DadoRetail.Api.Security;using DadoRetail.Application.Security;using DadoRetail.Infrastructure.Persistence;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;namespace DadoRetail.Api.Controllers;[ApiController,Route("api/v1/reports")]public sealed class ReportsController(DadoRetailDbContext db):ControllerBase{[HttpGet("dashboard"),HasPermission(Permissions.ReportView)]public async Task<IActionResult>Dashboard([FromQuery]Guid? storeId,CancellationToken ct){var sales=db.Sales.AsNoTracking().AsQueryable();if(storeId.HasValue)sales=sales.Where(x=>x.StoreId==storeId);var today=DateTime.UtcNow.Date;var todaySales=await sales.Where(x=>x.CreatedAtUtc>=today).ToListAsync(ct);var stock=await db.StockBalances.AsNoTracking().SumAsync(x=>(decimal?)x.Quantity,ct)??0;return Ok(new{salesToday=todaySales.Sum(x=>x.Total),checksToday=todaySales.Count,stockUnits=stock,products=await db.Products.CountAsync(ct),lowStock=await db.StockBalances.CountAsync(x=>x.Quantity<=5,ct)});}[HttpGet("stock"),HasPermission(Permissions.ReportView)]public async Task<IActionResult>Stock([FromQuery]Guid? warehouseId,CancellationToken ct){var q=db.StockBalances.AsNoTracking().AsQueryable();if(warehouseId.HasValue)q=q.Where(x=>x.WarehouseId==warehouseId);return Ok(await q.Join(db.Products,b=>b.ProductId,p=>p.Id,(b,p)=>new{b.WarehouseId,b.ProductId,p.Sku,p.Name,b.Quantity}).OrderBy(x=>x.Name).Take(5000).ToListAsync(ct));}[HttpGet("movements"),HasPermission(Permissions.ReportView)]public async Task<IActionResult>Movements([FromQuery]Guid? warehouseId,[FromQuery]DateTime? from,[FromQuery]DateTime? to,CancellationToken ct){var q=db.StockMovements.AsNoTracking().AsQueryable();if(warehouseId.HasValue)q=q.Where(x=>x.WarehouseId==warehouseId);if(from.HasValue)q=q.Where(x=>x.CreatedAtUtc>=from);if(to.HasValue)q=q.Where(x=>x.CreatedAtUtc<to);return Ok(await q.OrderByDescending(x=>x.CreatedAtUtc).Take(5000).ToListAsync(ct));}[HttpGet("inventory-differences"),HasPermission(Permissions.ReportView)]public async Task<IActionResult>InventoryDifferences(CancellationToken ct)=>Ok(await db.InventoryLines.AsNoTracking().Where(x=>x.ActualQuantity!=x.BookQuantity).Join(db.Products,l=>l.ProductId,p=>p.Id,(l,p)=>new{l.InventoryId,l.ProductId,p.Sku,p.Name,l.BookQuantity,l.ActualQuantity,Difference=l.ActualQuantity-l.BookQuantity}).Take(5000).ToListAsync(ct));}
